// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/workspaces", wrapper.ListWorkspaces)
	router.POST(options.BaseURL+"/workspaces", wrapper.CreateWorkspace)
	router.DELETE(options.BaseURL+"/workspaces/:workspaceId", wrapper.DeleteWorkspace)
	router.GET(options.BaseURL+"/workspaces/:workspaceId", wrapper.GetWorkspace)
	router.PUT(options.BaseURL+"/workspaces/:workspaceId", wrapper.UpdateWorkspace)
	router.POST(options.BaseURL+"/workspaces/:workspaceId/transfer-ownership", wrapper.TransferWorkspaceOwnership)
	router.GET(options.BaseURL+"/workspace-members", wrapper.ListWorkspaceMembers)
	router.POST(options.BaseURL+"/workspace-members", wrapper.AddWorkspaceMember)
	router.DELETE(options.BaseURL+"/workspace-members/:memberId", wrapper.RemoveWorkspaceMember)
	router.PUT(options.BaseURL+"/workspace-members/:memberId", wrapper.ChangeWorkspaceMemberRole)
	router.GET(options.BaseURL+"/audit-events", wrapper.ListAuditEvents)
}

